INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(11801, 'Esther 5:2', 'Esther', 5, 2, '&nbsp;کله چې بادشاه وکتل چې مَلِکه اِستَر دننه په دربار کښې ولاړه وه، نو بادشاه په هغې باندې مِهربانه شو او هغۀ خپله د سرو زرو امسا وراوږده کړه. بيا اِستَر ورنزدې شوه او د امسا سر له يې لاس وروړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11802, 'Esther 5:3', 'Esther', 5, 3, '&nbsp;بادشاه ترې نه تپوس وکړو، ”مَلِکه اِستَر خبره څۀ ده؟ ما ته ووايه چې تۀ څۀ غواړې، تۀ کۀ زما نيمه بادشاهى هم وغواړې نو تا ته به مِلاو شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11803, 'Esther 5:4', 'Esther', 5, 4, '&nbsp;اِستَر ورته په جواب کښې وفرمائيل، ”بادشاه سلامت، کۀ ستا رضا وى، نو زۀ دا دعوت درکوم چې تۀ او همان زما مېلمانۀ شئ په هغه مېلمستيا کښې چې ما تاسو دپاره کړې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11804, 'Esther 5:5', 'Esther', 5, 5, '&nbsp;بادشاه همان له حُکم ورکړو چې زر راشى، نو چې داسې دوئ د اِستَر مېلمانۀ شى. نو بادشاه او همان د اِستَر مېلمستيا له لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11805, 'Esther 5:6', 'Esther', 5, 6, '&nbsp;د ميو څښلو په وخت بادشاه د هغې نه تپوس وکړو، ”ما ته ووايه چې تۀ څۀ غواړې، نو تا ته به هغه مِلاو شى. زۀ به ستا درخواست منظور کړم، تر دې پورې کۀ تۀ زما نيمه بادشاهى هم وغواړې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11806, 'Esther 5:7', 'Esther', 5, 7, '&nbsp;اِستَر ورته وفرمائيل چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11807, 'Esther 5:8', 'Esther', 5, 8, '&nbsp;”بادشاه سلامت، کۀ تۀ په ما مِهربانه شې او زما عرض منظور کړې، نو زۀ غواړم چې تۀ او همان سبا زما په يوه بله مېلمستيا کښې مېلمانۀ شئ چې زۀ به يې تاسو دپاره تياروم. او سبا به درته ووايم چې زۀ څۀ غواړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11808, 'Esther 5:9', 'Esther', 5, 9, '&nbsp;کله چې همان د مېلمستيا نه لاړو نو هغه خوشحاله او ښۀ په سُر کښې وو. خو بيا هغۀ مردکے وليدو چې د محل د دروازې په خولۀ کښې وو او کله چې هغه تېرېدو نو مردکے ورته پانۀ څېدو او نۀ ورباندې د هغۀ رُعب څۀ اثر وکړو، نو همان ورته سخت غصه شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11809, 'Esther 5:10', 'Esther', 5, 10, '&nbsp;خو همان خپل ځان قابو کړو او کور ته لاړو. بيا هغۀ خپلو دوستانو له دعوت ورکړو چې کور ته يې راشى او خپلې ښځې زرش ته يې ووئيل چې د هغوئ سره شريکه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11810, 'Esther 5:11', 'Esther', 5, 11, '&nbsp;نو هغۀ ورته لافې وهلې، چې دے څومره مالداره دے او څومره ډېر زامن يې دى او بادشاه هغۀ له څومره اوچت مقام ورکړے دے او چې هغه د بادشاه د نورو ټولو آفسرانو نه څومره زيات اهم دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11811, 'Esther 5:12', 'Esther', 5, 12, '&nbsp;همان وئيل، ”د دې نه علاوه، مَلِکه اِستَر زما او د بادشاه نه بغېر بل هيچا له دعوت نۀ دے ورکړے، او سبا هغې ما له بيا سره د بادشاه دعوت راکړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11812, 'Esther 5:13', 'Esther', 5, 13, '&nbsp;خو چې ترڅو پورې يهودى مردکے د محل په دروازه کښې ناست وينم نو زما دپاره د دې هيڅ فائده نشته.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11813, 'Esther 5:14', 'Esther', 5, 14, '&nbsp;نو د هغۀ ښځې او خپلو ټولو دوستانو هغۀ له مشوره ورکړه، ”تۀ يو پينځويشت ګزه لوَړ دار ولې نۀ جوړوې؟ سبا سحر تۀ بادشاه ته ووايه چې مردکى په هغې باندې راځوړند کړى، نو بيا به تۀ ښۀ په خوشحالۍ سره مېلمستيا له لاړ شې.“ نو په همان دا خبره ښۀ ولګېده، او هغۀ هم هغه شان دار جوړ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11814, 'Esther 6:1', 'Esther', 6, 1, '&nbsp;هم په هغه شپه بادشاه له خوب نۀ ورتلو، نو هغۀ حُکم وکړو چې د بادشاهۍ د تاريخ کِتاب دې راوړے شى او هغۀ ته دې ولوستلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11815, 'Esther 6:2', 'Esther', 6, 2, '&nbsp;نو چې هغوئ کومه حِصه ولوستله په هغې کښې هغه واقعه شامله وه چې مردکى د بادشاه د وژلو منصوبه څنګه څرګنده کړه او هغه منصوبه کومه چې بِګتان او ترش، د محل دوو هغه خصيانو جوړه کړې وه، کومو چې د بادشاه د کوټو څوکيدارى کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11816, 'Esther 6:3', 'Esther', 6, 3, '&nbsp;بادشاه ترې نه تپوس وکړو، ”مونږ د دې په بدل کښې د مردکى څنګه درناوے کړے دے او څۀ مو اِنعام ورکړے دے؟“ نو د هغۀ نوکرانو جواب ورکړو، ”د هغۀ دپاره هيڅ نۀ دى شوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11817, 'Esther 6:4', 'Esther', 6, 4, '&nbsp;بادشاه تپوس وکړو، ”اوس په دربار کښې څوک دى؟“ نو همان ايله دربار ته ننوتو، هغه د دې دپاره راغلے وو چې د بادشاه نه تپوس وکړى چې مردکے په هغه دار باندې ځوړند کړى کوم چې هغۀ اوس تيار کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11818, 'Esther 6:5', 'Esther', 6, 5, '&nbsp;نو نوکرانو جواب ورکړو، ”همان په دربار کښې دے.“ بادشاه ورته ووئيل، ”هغه راپرېږدئ چې دننه راشى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11819, 'Esther 6:6', 'Esther', 6, 6, '&nbsp;نو همان راغلو او بادشاه ورته ووئيل، ”د يو کس نه چې زۀ خوشحاله شم نو د هغۀ څنګه عزت وکړم، زۀ د دې سړى دپاره څۀ وکړم؟“ همان د خپل ځان سره وئيل، ”داسې څوک شته چې بادشاه يې زما نه زيات عزت کول وغواړى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11820, 'Esther 6:9', 'Esther', 6, 9, '&nbsp;بيا د خپل لوئ عزتمند مشر په لاس دې سړى ته شاهى لباس ورواغونده او د ښار په کوڅو کښې يې په آس باندې سور بوځه. کله چې هغوئ روان وى نو هغه مشر سړے دې دا اِعلان کوى چې، وګورئ بادشاه چې د چا درناوے کول غواړى نو هغه يې داسې عزت کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11821, 'Esther 6:10', 'Esther', 6, 10, '&nbsp;بيا بادشاه همان ته ووئيل، ”زر شه او شاهى لِباس واخله او آس بوځه او د مردکى يهودى داسې درناوے وکړه. لکه څنګه چې تا مشوره راکړې ده نو د هغې په مطابق د هغۀ دپاره هغه هر څۀ وکړه. هغه به د محل د دروازې په خولۀ کښې ناست ووينې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11822, 'Esther 6:11', 'Esther', 6, 11, '&nbsp;نو همان شاهى لِباس واخستلو او مردکى ته يې ورواغوستلو او د بادشاه په آس يې سور کړو او همان هغه د ښار په کوڅو کښې بوتلو او خلقو ته يې اِعلان کولو چې، ”وګورئ چې بادشاه د چا درناوے کول وغواړى نو هغه يې داسې عزت کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11823, 'Esther 6:12', 'Esther', 6, 12, '&nbsp;نو مردکے بيا واپس د محل دروازې ته راواپس شو خو په دې دوران کښې همان خفه او شرمنده کور ته تېز لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11824, 'Esther 6:13', 'Esther', 6, 13, '&nbsp;هغۀ خپلې ښځې او ټولو دوستانو ته هغه هر څۀ ووئيل چې څۀ شوى وُو. بيا هغې او د هغۀ هوښيارو ملګرو هغۀ ته ووئيل، ”په مردکى باندې ستا هيڅ زور نۀ رسى. هغه يو يهودى دے او ځکه تۀ په هغۀ باندې برے نۀ شې موندلے. هغه به خامخا تا له شکست درکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11825, 'Esther 6:14', 'Esther', 6, 14, '&nbsp;کله چې هغوئ لا خبرې کولې، نو د محل خصيان راورسېدل او همان يې د اِستَر مېلمستيا له بوتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11826, 'Esther 7:1', 'Esther', 7, 1, '&nbsp;نو بادشاه او همان د اِستَر سره روټۍ خوړلو له لاړل', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11827, 'Esther 7:2', 'Esther', 7, 2, '&nbsp;او دا دوېم ځل وو. د ميو څښلو په وخت بادشاه د هغې نه بيا تپوس وکړو، ”مَلِکه اِستَر، اوس چې تۀ زما نه څۀ هم وغواړې نو تا ته به مِلاو شى. زۀ به تا له زما نيمه بادشاهى هم درکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11828, 'Esther 7:3', 'Esther', 7, 3, '&nbsp;مَلِکه اِستَر جواب ورکړو، ”بادشاه سلامت، کۀ ستا رضا وى نو زما دا يو عاجزانه سوال قبول کړه، زما خواهش دا دے چې زما او زما د خلقو ژوند بچ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11829, 'Esther 7:4', 'Esther', 7, 4, '&nbsp;زۀ او زما خلق د حلالولو، او ختمولو دپاره خرڅ کړے شوى يُو. کۀ مونږ صرف د نوکرانو په حيثيت خرڅ شوے وے، نو زۀ به خاموش پاتې وے او دا تکليف به مې نۀ درکولے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11830, 'Esther 7:5', 'Esther', 7, 5, '&nbsp;اخسويرس بادشاه د مَلِکه نه تپوس وکړو، ”د داسې کار کولو جرأت څوک کولے شى؟ هغه سړے چرته دے؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11831, 'Esther 7:6', 'Esther', 7, 6, '&nbsp;اِستَر جواب ورکړو، ”زمونږ دشمن، ظالم او هغه مکار سړے دا همان دے.“ نو د همان رنګ د بادشاه او مَلِکه په مخکښې تک زېړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11832, 'Esther 7:7', 'Esther', 7, 7, '&nbsp;بادشاه په غصه کښې پاڅېدو، د مېلمستيا نه روان شو او د محل باغونو ته بهر لاړو. همان ته پته ولګېده چې بادشاه د هغۀ د وژلو اراده لرى، نو هغه ايسار شو د دې دپاره چې اِستَر ته د خپل ژوند د بچ کولو سوال وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11833, 'Esther 7:8', 'Esther', 7, 8, '&nbsp;هغۀ د مِنت زارۍ دپاره خپل ځان د اِستَر په کټ باندې وروغورزولو نو هم په هغه وخت بادشاه د باغونو نه واپس کوټې ته راغلو او چې دا يې وليدل نو بادشاه چغه کړه چې، ”دا سړے دلته هم زما په خپل محل کښې زما په وړاندې اِستَر ته لاس وراچوى؟“ بادشاه چې څنګه دا ووئيل نو خصيانو د همان مخ پټ کړو چې قتل کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11834, 'Esther 7:9', 'Esther', 7, 9, '&nbsp;نو د بادشاه يو خصى، خربونا ووئيل، ”ګورئ، همان خو د مردکى د راځوړندولو دپاره په کور کښې پينځويشت ګزه اوچت يو دار جوړ کړے دے. بادشاه سلامت، مردکى هغه څوک دے چې چا ستا ژوند بچ کړے وو.“ بادشاه حُکم وکړو، ”همان په دې باندې ځوړند کړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11835, 'Esther 7:10', 'Esther', 7, 10, '&nbsp;نو همان په هغه دار باندې ځوړند کړے شو کوم چې د مردکى دپاره جوړ شوے وو. او بيا د بادشاه غصه سړه شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11836, 'Esther 8:1', 'Esther', 8, 1, '&nbsp;هم په هغه وخت اخسويرس بادشاه مَلِکه اِستَر له د همان ټول جائيداد ورکړو، دا هم هغه همان وو کوم چې د يهوديانو دشمن وو. اِستَر بادشاه ته وفرمائيل چې مردکى د هغې خپلوان دے، نو د هغه وخت نه مردکى ته دا اجازت وو چې د بادشاه حضور ته دننه راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11837, 'Esther 8:2', 'Esther', 8, 2, '&nbsp;بادشاه خپله هغه ګوتمه وويستله چې مهر ورباندې وو او چې کومه يې د همان نه واپس اخستې وه او مردکى له يې ورکړه. اِستَر مردکى د همان د جائيداد مشر جوړ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11838, 'Esther 8:3', 'Esther', 8, 3, '&nbsp;نو اِستَر بادشاه له بيا لاړه او د هغۀ په پښو پرېوته، وې ژړل او مِنت زارى يې ورته وکړه چې د هغه خرابې منصوبې خِلاف څۀ وکړى کومه چې د اجاج اولاد همان د يهوديانو خِلاف جوړه کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11839, 'Esther 8:4', 'Esther', 8, 4, '&nbsp;بادشاه هغې ته خپله د سرو زرو امسا بيا وراُږده کړه، نو هغه ودرېده او وې فرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11840, 'Esther 8:5', 'Esther', 8, 5, '&nbsp;”بادشاه سلامت، کۀ ستا رضا وى او کۀ تا سره زما فکر وى او دا تا ته ښۀ ښکارى، نو مِهربانى وکړه چې دا فرمان جارى کړه چې د همان په حُکم باندې دې عمل نۀ کيږى، دا هغه حُکم وو چې د اجاج قبيلې د همداتا زوئ همان د ټولو يهوديانو د وژلو دپاره ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11841, 'Esther 8:6', 'Esther', 8, 6, '&nbsp;کۀ دا افت زما په خلقو باندې راشى او چې زما خپلوان ووژلے شى نو بيا زۀ دا څنګه برداشت کولے شم؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11842, 'Esther 8:7', 'Esther', 8, 7, '&nbsp;بيا اخسويرس بادشاه مَلِکه اِستَر او مردکى يهودى ته ووئيل، ”ګورئ، ما همان د يهوديانو خِلاف د منصوبې په وجه پهانسى کړے دے او ما اِستَر له د هغۀ جائيداد هم ورکړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11843, 'Esther 8:8', 'Esther', 8, 8, '&nbsp;خو د بادشاه په نوم چې کوم فرمان جارى شوے وى او په هغې باندې شاهى مهر لګولے شوے وى نو هغه نۀ واپس کيږى. خو يهوديانو ته هغه څۀ ليکلے شئ څۀ چې ستاسو زړۀ غواړى، او دا زما په نوم ليکلے شئ او شاهى مهر ورباندې ولګولے شئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11844, 'Esther 8:9', 'Esther', 8, 9, '&nbsp;نو د درېمې مياشتې يعنې د سيوان د مياشتې په درويشتمه ورځ داسې وشول. مردکى د بادشاه منشيان راوغوښتل او يهوديانو، حکمرانانو، وزيرانو او د هِندوستان نه واخله تر ايتهوپيا پورې د يو سل او اوويشتو صُوبو آفسرانو ته يې خطونه وليکل. خطونه هرې صُوبې ته په خپله ژبه او رسم‌الخط کښې او يهوديانو ته په خپله ژبه او رسم‌الخط کښې ليکلے شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11845, 'Esther 8:10', 'Esther', 8, 10, '&nbsp;مردکى خطونه د اخسويرس بادشاه د طرف نه ليکلى وُو او په دې باندې يې شاهى مهر لګولے وو. دا په هغه تېزو آسونو باندې سوارو کسانو په ذريعه رسولے شوى وُو چې کوم آسونه د بادشاه دپاره ساتلے شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11846, 'Esther 8:11', 'Esther', 8, 11, '&nbsp;په دې خطونو کښې دا تفصيل وو چې بادشاه به په هر ښار کښې يهوديانو له دا اجازت ورکړى چې د خپلو ځانونو د حِفاظت دپاره متحد شى. کۀ د يو قوم فوجيان په هره يوه صُوبه کښې په يهودى سړو باندې، د هغوئ بچو او ښځو باندې حمله وکړى، نو يهوديان به هم ورباندې حمله کوى او حمله کوونکى به تباه کړى، هغوئ دې تر آخرى کس پورې ووژنى او د هغوئ هر څۀ دې لوټ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11847, 'Esther 8:12', 'Esther', 8, 12, '&nbsp;دا فرمان د فارس په ټول سلطنت کښې په هغه ورځ عملى کولے شو چې کومه د يهوديانو د وژلو دپاره مقرره وه، دا د دولسمې يعنې د ادر مياشتې ديارلسمه ورځ وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11848, 'Esther 8:13', 'Esther', 8, 13, '&nbsp;د دې قانونى اِعلان شوے وو او په هره صُوبه کښې هر څوک د دې نه خبر وُو، نو چې کله هغه ورځ راشى نو يهوديان به د دشمن نه د بدل اخستلو دپاره تيار وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11849, 'Esther 8:14', 'Esther', 8, 14, '&nbsp;د بادشاه په حُکم په شاهى آسونو سوارۀ پېغام وړُونکى تېز لاړل. هغه فرمان په مرکزى ښار سوسه کښې هم جارى شوے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11850, 'Esther 8:15', 'Esther', 8, 15, '&nbsp;مردکے د محل نه لاړو چې شاهى لِباس يعنې آسمانى او سپين رنګ جامې، د کاسنى رنګ د مهينې لټې يوه چُوغه يې اغوستې وه او د سرو زرو يو زبردست تاج يې په سر وو. بيا د سوسه کوڅې د لاسونو د پړقارى او د خوشحالۍ د چغو نه ډکې شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11851, 'Esther 8:16', 'Esther', 8, 16, '&nbsp;يهوديانو خوشحالى، راحت، خندا او عزت محسوسولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11852, 'Esther 8:17', 'Esther', 8, 17, '&nbsp;هر ښار او هرې صُوبې ته هم چې د بادشاه فرمان ورسېدو، نو يهوديان خوشحاله وُو. هغوئ مېلمستيا او جشن وکړو. او په هغوئ کښې نور ډېر خلق په دې وجه يهوديان شول، ځکه چې د يهوديانو نه يرېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11853, 'Esther 9:1', 'Esther', 9, 1, '&nbsp;د ادر مياشتې ديارلسمه ورځ راغله، دا هغه ورځ وه چې په دې باندې شاهى فرمان عملى کول وُو، هغه ورځ چې د يهوديانو دشمنانو دا اُميد لرلو چې يهوديان به د خپل طاقت لاندې راولى. خو يهوديانو ورباندې فتح وموندله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11854, 'Esther 9:2', 'Esther', 9, 2, '&nbsp;د اخسويرس په ټوله بادشاهۍ کښې يهوديان په خپلو ښارونو کښې د هغه چا خِلاف يو شول چا چې په هغوئ د حملې کوشش کولو. د هر ځائ خلق د هغوئ نه يرېدل او هيچا د هغوئ مقابله نۀ شوه کولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11855, 'Esther 9:3', 'Esther', 9, 3, '&nbsp;د صُوبو ټولو آفسرانو، حکمرانانو، وزيرانو او شاهى نمائندګانو د يهوديانو مدد په دې وجه وکړو چې هغوئ د مردکى نه يرېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11856, 'Esther 9:4', 'Esther', 9, 4, '&nbsp;په ټوله بادشاهۍ کښې دا ښۀ مشهوره وه چې مردکى اوس په محل کښې يو تکړه سړے وو او نور هم تکړه کېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11857, 'Esther 9:5', 'Esther', 9, 5, '&nbsp;نو په هغه ورځو کښې يهوديانو خپل دشمنان په تُورو ووژل او نيست او نابود يې کړل. او چا چې د يهوديانو نه نفرت کولو د هغوئ سره يې د خپلې مرضى په مطابق عمل وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11858, 'Esther 9:6', 'Esther', 9, 6, '&nbsp;د سوسه په مرکزى ښار کښې يهوديانو پينځۀ سوه کسان ووژل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11859, 'Esther 9:11', 'Esther', 9, 11, '&nbsp;هم په هغه ورځ بادشاه خبر کړے شو چې په سوسه کښې څومره کسان وژلے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11860, 'Esther 9:12', 'Esther', 9, 12, '&nbsp;بيا بادشاه مَلِکه اِستَر ته ووئيل، ”صِرف د سوسه په قلعه کښې يهوديانو پينځۀ سوه کسان وژلى دى، چې په دې کښې د همان زامن هم شامل دى. چې دلته دومره زيات وژلے شوى دى نو په صُوبو کښې به څۀ شوى وى. اوس تۀ څۀ غواړې؟ تۀ ووايه کۀ نور څۀ هم غواړې نو در به کړے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11861, 'Esther 9:13', 'Esther', 9, 13, '&nbsp;اِستَر ورته په جواب کښې وفرمائيل، ”بادشاه سلامت، کۀ ستا رضا وى، نو يهوديانو له سبا په سوسه کښې يو ځل بيا د نن په شان اجازت ورکړه. او دا حُکم ورکړه چې د همان د لسو زامنو لاشونه په دار باندې ځوړند کړے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11862, 'Esther 9:14', 'Esther', 9, 14, '&nbsp;نو بادشاه حُکم وکړو چې داسې دې وشى او په سوسه کښې دا فرمان جارى شو. د همان د لسو زامنو لاشونه په دار راځوړند کړے شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11863, 'Esther 9:15', 'Esther', 9, 15, '&nbsp;د ادر مياشتې په څوارلسمه ورځ د سوسه يهوديان يو ځل بيا يو ځائ شول او په ښار کښې يې درې سوه نور کسان ووژل. خو هغوئ بيا هم څۀ لوټ مار ونۀ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11864, 'Esther 9:16', 'Esther', 9, 16, '&nbsp;يهوديان په صُوبو کښې هم د خپلو ځانونو د حِفاظت دپاره راغونډ شول. هغوئ د خپلو دشمنانو نه داسې ځانونه خلاص کړل چې پينځۀ اويا زره يې هغه کسان ووژل چا چې د هغوئ نه نفرت کولو. خو هغوئ لوټ مار ونۀ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11865, 'Esther 9:17', 'Esther', 9, 17, '&nbsp;دا د ادر د مياشتې په ديارلسمه ورځ باندې وشول. په ورپسې ورځ يعنې په څوارلسمه ورځ باندې نور قتلونه ونۀ شول او هغوئ په دې ورځ د خوشحالۍ نه يې مېلمستيا وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11866, 'Esther 9:18', 'Esther', 9, 18, '&nbsp;خو د سوسه يهوديانو پينځلسمه ورځ د چُهټۍ ورځ وګرځوله، ځکه چې هغوئ په ديارلسمه او څوارلسمه ورځ باندې خپل دشمنان وژلى وُو او په پينځلسمه ورځ يې وژل بس کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11867, 'Esther 9:19', 'Esther', 9, 19, '&nbsp;نو په دې وجه هغه يهوديان کوم چې په کلو کښې اوسيږى هغوئ د ادر د مياشتې په څوارلسمه ورځ د خوشحالۍ چُهټى کوى، په دې وخت باندې هغوئ مېلمستيا کوى او يو بل له د خوراک دپاره تُحفې ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11868, 'Esther 9:20', 'Esther', 9, 20, '&nbsp;مردکى دا واقعې ليکلې وې او د فارس په ټول سلطنت کښې نزدې او لرې ټولو يهوديانو له يې خطونه لېږلى وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11869, 'Esther 9:21', 'Esther', 9, 21, '&nbsp;هغوئ ته يې وئيلى وُو چې هر کال د ادر مياشتې په څوارلسمه او پينځلسمه ورځ اختر کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11870, 'Esther 9:22', 'Esther', 9, 22, '&nbsp;دا هغه ورځې وې چې په هغې باندې يهوديانو د خپلو دشمنانو نه ځانونه خلاص کړل، دا هغه مياشت وه چې د غم او د خفګان وخت نه په خندا او خوشحالۍ باندې بدله شوې وه. هغوئ ته وئيلے شوى وُو چې په دې ورځو باندې خوشحالى او مېلمستيا وکړئ او يو بل او غريبانانو له د خوراک دپاره تُحفې ورکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11871, 'Esther 9:23', 'Esther', 9, 23, '&nbsp;نو يهوديانو د مردکى په اصُولو باندې عمل وکړو او دا اختر د هر کال رِواج جوړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11872, 'Esther 9:24', 'Esther', 9, 24, '&nbsp;د همداتا زوئ همان چې د اجاج د اولاد نه وو او د يهوديانو دشمن وو، هغۀ پچه واچوله چې دا پوريم بللے شوه، دا د دې دپاره وه چې د يهوديانو د تباهۍ ورځ معلومه کړى، هغۀ دا منصوبه جوړه کړې وه چې هغوئ صفا ختم کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11873, 'Esther 9:25', 'Esther', 9, 25, '&nbsp;خو اِستَر بادشاه له لاړه او بادشاه د دې نتيجې سره يو ليکلے فرمان جارى کړو چې همان د يهوديانو دپاره کومه منصوبه جوړه کړې وه نو هغه ورته اولټه راوګرځېده او هغه او د هغۀ زامن په دار باندې پهانسى کړے شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11874, 'Esther 9:26', 'Esther', 9, 26, '&nbsp;نو ځکه هغې ته د پوريم اختر وائى، پخوا زمانه کښې به دا لفظ د پچى اچولو دپاره استعمالېدو. د مردکى د خطونو په وجه او د هغه هر څۀ په وجه چې په هغوئ شوى وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11875, 'Esther 9:27', 'Esther', 9, 27, '&nbsp;يهوديانو د خپلو ځانونو، د خپل اولاد او د هغه چا دپاره دا اصُول جوړ کړو چې څوک يهودى شى، نو هر کال به په صحيح وخت باندې دا دوه ورځې په باقاعدګۍ سره د مردکى د اصُولو په مطابق مناووى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11876, 'Esther 9:28', 'Esther', 9, 28, '&nbsp;دا فېصله شوې وه چې د يهوديانو د خاندان راتلونکے هر يو نسل چې په هره صُوبه يا ښار کښې وى په راتلونکى ټولو وختونو کښې به د پوريم دا ورځې يادې ساتى او دا ورځې به مناووى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11877, 'Esther 9:29', 'Esther', 9, 29, '&nbsp;بيا د ابى‌خېل لور مَلِکه اِستَر هم، د مردکى سره يو خط وليکلو او چې مردکى کوم خط د پوريم په باره کښې مخکښې ليکلے وو د هغې د تصديق دپاره هغې خپل ټول ليکلے اختيار هم شامل کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11878, 'Esther 9:30', 'Esther', 9, 30, '&nbsp;دا خط د ټولو يهوديانو دپاره وو او د دې نقلونه د فارس سلطنت ټولو يو سل او اوويشتو صُوبو ته لېږلے شوى وُو. په دې کښې د يهوديانو خېر او امن غوښتے شوے وو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11879, 'Esther 9:31', 'Esther', 9, 31, '&nbsp;او هغوئ او د هغوئ اولاد ته يې دا نصيحت کړے وو چې په صحيح وخت باندې د پوريم ورځې هم هغه شان مناو کړى، لکه څنګه چې هغوئ د روژو د نيولو او د غم د وخت اصُول خپل کړى دى. د دې حُکم مردکى او مَلِکه اِستَر دواړو کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11880, 'Esther 9:32', 'Esther', 9, 32, '&nbsp;د اِستَر هغه حُکم کوم چې د پوريم د اصُولو پوره کېدل وو هغه په يو کِتاب کښې ليکلے شوے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11881, 'Esther 10:1', 'Esther', 10, 1, '&nbsp;اخسويرس بادشاه د خپلې بادشاهۍ نه د سمندر د غاړې پورې محصُول اخستلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11882, 'Esther 10:2', 'Esther', 10, 2, '&nbsp;هغۀ چې کوم لوئ او عجيبه کارونه کړى وُو او هم داسې هغه ټوله قيصه چې هغۀ مردکى له د اوچتې عُهدې ترقى څنګه ورکړه، دا د فارس او مادى د بادشاهانو د تاريخ په کِتاب کښې ليکلے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11883, 'Esther 10:3', 'Esther', 10, 3, '&nbsp;مردکى يهودى په عهده کښې په بادشاه پسې دوېم کس وو. د خپلو يهوديانو هغه ډېر خوښ وو او ډېر عزتمند وو. هغۀ د خپلو خلقو د فائدې دپاره او د ټولو يهوديانو د ګټې دپاره کار کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11884, 'Job 1:1', 'Job', 1, 1, '&nbsp;په يوه زمانه کښې د عُوض په مُلک کښې يو سړے وو چې نوم يې ايُوب وو. دا يو بې‌داغه او نېک سړے وو، هغه يو داسې کس وو چې د خُدائ پاک نه يرېدو او د بدۍ نه يې ځان ساتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11885, 'Job 1:2', 'Job', 1, 2, '&nbsp;د هغۀ اووۀ زامن او درې لوڼه وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11886, 'Job 1:3', 'Job', 1, 3, '&nbsp;هغۀ سره اووۀ زره ګډې، درې زره اوښان، د غوَيانو پينځۀ سوه قلبې، پينځۀ سوه خرې وې او ډېر زيات نوکران يې وُو، نو دے د مشرقى علاقې په خلقو کښې د ټولو نه زيات مالداره وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11887, 'Job 1:4', 'Job', 1, 4, '&nbsp;د هغۀ زامنو په خپلو کورونو کښې وار په وار مېلمستيا کوله، او هغوئ به خپلو درې واړو خوېندو له دعوت ورکولو چې د هغوئ سره خوراک څښاک وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11888, 'Job 1:5', 'Job', 1, 5, '&nbsp;او کله به چې د مېلمستيا ورځ تېره شوه، نو ايُوب به سحر وختى پاڅېدو او د هر يو بچى دپاره يې د ګناه نه د پاکوالى سوزېدونکې نذرانه پېش کوله، ايُوب به همېشه دا کار د دې دپاره کولو چې د هغۀ خيال وو چې کېدے شى چې زما بچو ګناه کړې وى او په خپلو زړُونو کښې يې خُدائ پاک ته بدرد وئيلى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11889, 'Job 1:6', 'Job', 1, 6, '&nbsp;يو ځل آسمانى مخلوق راغلل چې خپل ځانونه د مالِک خُدائ په مخکښې حاضر کړى او شېطان هم د هغوئ سره راغلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11890, 'Job 1:7', 'Job', 1, 7, '&nbsp;مالِک خُدائ شېطان ته وفرمائيل، ”تا څۀ کول؟“ نو شېطان مالِک خُدائ ته ووئيل، ”زۀ په دُنيا کښې ګرځېدم راګرځېدم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11891, 'Job 1:8', 'Job', 1, 8, '&nbsp;نو مالِک خُدائ شېطان ته وفرمائيل، ”ستا زما د خِدمت کوونکى ايُوب په باره کښې څۀ خيال دے؟ ګوره په دُنيا کښې د هغۀ په شان هيڅ څوک هم نشته، هغه يو بې‌داغه او نېک سړے دے چې هغه د خُدائ پاک نه يريږى او د بدۍ نه ځان ساتى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11892, 'Job 1:9', 'Job', 1, 9, '&nbsp;بيا شېطان مالِک خُدائ ته ووئيل، ”آو، خو ايُوب په څۀ وجه د خُدائ پاک نه يريږى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11893, 'Job 1:10', 'Job', 1, 10, '&nbsp;تا همېشه د هغۀ، د هغۀ د کور او د هغۀ د هر څۀ حِفاظت کړے دے، تا هغۀ له په هر کار کښې برکت ورکړے دے او په دې مُلک کښې تا هغۀ له بې‌شمېره رَمې ورکړې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11894, 'Job 1:11', 'Job', 1, 11, '&nbsp;خو کۀ تۀ اوس د هغۀ نه هغه هر څۀ واخلې نو هغه به ستا په حضور کښې په تا لعنت ووائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11895, 'Job 1:12', 'Job', 1, 12, '&nbsp;نو مالِک خُدائ شېطان ته وفرمائيل، ”بلکل ټيک ده د هغۀ سره چې هر څۀ دى هغه ستا په اختيار کښې دى، خو چې هغه تباه نۀ کړې.“ نو شېطان د مالِک خُدائ د حضور نه لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11896, 'Job 1:13', 'Job', 1, 13, '&nbsp;يوه ورځ چې د هغۀ زامنو او لوڼو د خپل مشر ورور په کور کښې روټۍ خوړله او مے يې څښل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11897, 'Job 1:14', 'Job', 1, 14, '&nbsp;نو يو پېغام وړونکے ايُوب له راغلو او ورته يې ووئيل، ”غوَيانو يوې کولې او خرې يې په څنګ کښې څرېدلې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11898, 'Job 1:15', 'Job', 1, 15, '&nbsp;او د سبائيانو څۀ خلقو حمله وکړه او څاروى يې بوتلل او نوکران يې په تُوره ووژل، يواځې زۀ ژوندے پاتې يم چې تا خبر کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11899, 'Job 1:16', 'Job', 1, 16, '&nbsp;هغۀ لا خبرې ختمې کړې نۀ وې چې يو بل کس راغلو او وې وئيل، ”د خُدائ پاک تندر د آسمان نه راوغورزېدو او ګډې او نوکران يې وسوزول او هلاک يې کړل، يواځې زۀ ژوندے يم چې تا خبر کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11900, 'Job 1:17', 'Job', 1, 17, '&nbsp;کله چې هغۀ لا خبرې کولې، نو يو بل کس راغلو او وې وئيل، ”کسديانو درې قبيلې جوړې کړې، او حمله يې وکړه او اوښان يې بوتلل او نوکران يې په تُوره باندې ووژل، يواځې زۀ ژوندے پاتې يم چې تا خبر کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');